import math
def sqrt_root(n):
    if n < 0:
        return None
    x = n
    y = 1
    while (x - y) > 0.00001:
        mid = (x + y) / 2
        if mid * mid == n:
            return mid
        elif mid * mid < n:
            x = mid
        else:
            y = mid
    return x
