def find_Max(arr, low, high):
    if (low > high):
        return None
    mid = (low + high)//2
    if (mid < high-1 and arr[mid] > arr[mid+1]):
        return arr[mid]
    if (arr[high] >= arr[mid] and arr[mid] > arr[low]):
        return find_Max(arr,mid+1,high)
    if (arr[low] <= arr[mid] and arr[mid] < arr[high]):
        return find_Max(arr,low,mid-1)
    return find_Max(arr,mid+1,high)
```

